fn get(v: &Vec<Int>, i: Int) -> Option<Int> {
    let result = match i >= 0 && i < len(&v) {
        True => Some(v.get(i)),
        False => None,
    }
    match result {
        Some(r) => r,
        None => Option.none(),
    }
}

fn filter(v: &Vec<Int>, pred: &FnMutlich<Int>) -> Vec<Int> {
    let mut result = vec()
    for i in range(0, len(&v)) {
        let val = get(&v, i)
        match val {
            Some(x) => {
                let res = pred(x)
                match res {
                    True => {
                        let r = clone(&x)
                        result = push(result, r)
                    },
                    False => {
                        let _r = clone(&x)
                    },
                }
            },
            None => {
                let _r = clone(&val)
            },
        }
    }
    result
}

